import React, { Component } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import {
  Row, Col, Form, Input, Button, DatePicker,
  notification, Alert
} from 'antd'
import _ from 'lodash/lang'
import queryString from 'query-string'
import Footer from '../../components/Footer/footer'
import IntlMessages from '../../components/utility/intlMessages'
import TokopediaCrackScreenStyle from './index.style'
import { LANG_STRING, FORM_DATA } from './constants'
import NumericInput from '../../components/NumericInput'
import actions from '../../redux/tokopediaCrackScreenEndorse/actions'
import CircularLoader from '../../components/CircularLoader'

const FormItem = Form.Item
const { postTokopediaCrackScreenForm, resetTokopediaCrackScreenEndorseRedux } = actions
class TokopediaCrackScreenEndorsement extends Component {
  constructor (props) {
    super(props)
    this.state = {
      internalId: null
    }
  }

  componentDidMount () {
    const query = queryString.parse(window.location.search)
    let splitQueryId = query.id.split('?')
    let decodedString = decodeURI(splitQueryId[0])
    this.setState({
      internalId: decodedString.trim()
    })
    this.scrollToView()
  }

  componentWillReceiveProps (nextProps) {
    const {
      tokopediaCrackScreenMessage, tokopediaCrackScreenError
    } = nextProps
    if (tokopediaCrackScreenError && (typeof tokopediaCrackScreenMessage === 'string') &&
      (tokopediaCrackScreenMessage && tokopediaCrackScreenMessage !== 'success')
    ) {
      notification[tokopediaCrackScreenError ? 'error' : 'success']({
        message: this.intlText({ id: 'Error' }),
        description: tokopediaCrackScreenError && tokopediaCrackScreenMessage
          ? this.intlText({ id: tokopediaCrackScreenMessage }) : ''
      })
      this.props.resetTokopediaCrackScreenEndorseRedux(['tokopediaCrackScreenMessage'])
    } else if (_.isArray(tokopediaCrackScreenMessage)) {
      // this form showing the error in each field name if any
      tokopediaCrackScreenMessage.forEach(item => {
        this.props.form.setFields({
          [item.key]: {
            value: item.val,
            errors: [new Error(item.err)]
          }
        })
      })
      this.props.resetTokopediaCrackScreenEndorseRedux(['tokopediaCrackScreenMessage'])
    }

    if (tokopediaCrackScreenMessage === 'success') {
      // no need to show notification success if we are showing
      // thank you template for the form submission
      this.scrollToView()
    }
  }

  scrollToView = () => {
    // scroll the body if user load to bottom
    setTimeout(() => {
      document.body.scrollIntoView({
        behavior: 'smooth'
      })
    }, 20)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form } = this.props
    const formBody = form.getFieldsValue()
    this.props.postTokopediaCrackScreenForm({
      body: {
        ...formBody,
        dob: formBody.dob.format('YYYY-MM-DD'),
        phone_no: `62-${formBody.phone_no}`
      },
      params: { id: this.state.internalId }
    })
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  getFormItems = (formData) => {
    const { getFieldDecorator } = this.props.form
    const FormLabel = (
      <label className='form-label'>
        <IntlMessages id={formData.name} /><span className='warning-color'>*</span>
      </label>
    )
    switch (formData.type) {
      case 'alphanumeric':
        return (
          <Col key={formData.formName}>
            {FormLabel}
            <FormItem>
              {
                getFieldDecorator(formData.formName, {
                  rules: [
                    {
                      required: true,
                      message: (<IntlMessages id={LANG_STRING.requiredField} />)
                    },
                    { validator: formData.validator }
                  ],
                  initialValue: ''
                })(<Input />)
              }
            </FormItem>
          </Col>
        )
      case 'numeric':
        return (
          <Col key={formData.formName}>
            {FormLabel}
            <FormItem>
              {
                getFieldDecorator(formData.formName, {
                  rules: [
                    {
                      required: true,
                      message: (<IntlMessages id={LANG_STRING.requiredField} />)
                    },
                    { validator: formData.validator }
                  ],
                  initialValue: ''
                })(<NumericInput
                  addonBefore={formData.formName === 'phone_no' ? '+62' : ''}
                  minLength={formData.minLength || 10}
                  maxLength={formData.maxLength || 30}
                />)
              }
              {
                formData.formName === 'imei' &&
                <div className='imei-info'>
                  <i className='fas fa-star imei-star' />
                  <IntlMessages id={LANG_STRING.imeiInfo} />
                </div>
              }
            </FormItem>
          </Col>
        )
      case 'dob':
        return (
          <Col key={formData.formName}>
            {FormLabel}
            <FormItem>
              {
                getFieldDecorator(formData.formName, {
                  rules: [
                    {
                      required: true,
                      message: (<IntlMessages id={LANG_STRING.requiredField} />)
                    },
                    { validator: formData.validator }
                  ],
                  initialValue: ''
                })(
                  <DatePicker
                    format={'YYYY-MM-DD'}
                    placeholder={this.intlText({ id: LANG_STRING.selectDate })}
                  // disable selection above today
                  />
                )
              }
            </FormItem>
          </Col>
        )
      default:
        break
    }
  }

  render () {
    const { internalId } = this.state
    const { tokopediaCrackScreenLoading, tokopediaCrackScreenMessage } = this.props
    return (
      <React.Fragment>
        <TokopediaCrackScreenStyle>
          <Row type='flex' justify='center' id='tokopediaCrackScreenForm'>
            <Col xs={22} sm={24} md={12} lg={12} xl={12} className='crack-screen-container'>
              {
                internalId ? (
                  <CircularLoader isSpining={!!tokopediaCrackScreenLoading} size='24px'>
                    {(tokopediaCrackScreenMessage !== 'success')
                      ? (
                        <React.Fragment>
                          <div>
                            <h2><IntlMessages id={LANG_STRING.title} /></h2>
                            <IntlMessages id={LANG_STRING.subtitle} />
                          </div>
                          <Form onSubmit={this.handleFormSubmit} id='myForm'>
                            <div className='form-container-body'>
                              {
                                FORM_DATA.map(val => this.getFormItems(val))
                              }
                              <Button
                                type='primary'
                                className='form-btn'
                                htmlType='submit'
                                form='myForm'
                                key='submit'
                              >
                                <IntlMessages id={LANG_STRING.submit} />
                              </Button>
                            </div>
                          </Form>
                        </React.Fragment>
                      )
                      : (
                        <div>
                          <h2><IntlMessages id={LANG_STRING.thankYou} /></h2>
                          <IntlMessages id={LANG_STRING.successMsg} />
                        </div>
                      )
                    }
                  </CircularLoader>
                )
                  : (
                    <Alert
                      message='Error'
                      description={this.intlText({ id: LANG_STRING.authrization })}
                      type='error'
                    />
                  )
              }
            </Col>
          </Row>
        </TokopediaCrackScreenStyle>
        <Footer />
      </React.Fragment>
    )
  }
}
const TokopediaCrackScreenWrapped = Form.create()(TokopediaCrackScreenEndorsement)
export default connect(
  state => ({
    tokopediaCrackScreenMessage: state.TokopediaCrackScreenEndorse.tokopediaCrackScreenMessage,
    tokopediaCrackScreenDetails: state.TokopediaCrackScreenEndorse.tokopediaCrackScreenDetails,
    tokopediaCrackScreenLoading: state.Loading.SUBMIT_TOKOPEDIA_CRACK_SCREEN_FORM,
    tokopediaCrackScreenError: state.Error.SUBMIT_TOKOPEDIA_CRACK_SCREEN_FORM
  }),
  {
    postTokopediaCrackScreenForm,
    resetTokopediaCrackScreenEndorseRedux
  }
)(injectIntl(TokopediaCrackScreenWrapped))
